(()=>{'use strict';
const key='options-desk-appearance-v1',defaults={stockUp:'#b9ee81',stockDown:'#ee9393',premiumUp:'#54cce8',premiumDown:'#f3ad64',theme:'midnight',accent:'lime',density:'comfortable',height:510,layout:'standard',marketOnly:false,showList:true,showChain:true,showPositions:true,colorblind:false,chartStyle:'1',marketInterval:'15'},valid={theme:['midnight','graphite','ocean','plum','paper','contrast'],accent:['lime','cyan','violet','amber'],density:['comfortable','compact'],layout:['standard','wide'],chartStyle:['1','2','3'],marketInterval:['1','5','15','60','D']};let state={...defaults};
try{const saved=JSON.parse(localStorage.getItem(key)||'{}');for(const k of Object.keys(defaults)){if(/^(stock|premium)(Up|Down)$/.test(k)&&/^#[0-9a-f]{6}$/i.test(saved[k]||''))state[k]=saved[k];else if(valid[k]?.includes(saved[k]))state[k]=saved[k];else if(typeof defaults[k]==='boolean'&&typeof saved[k]==='boolean')state[k]=saved[k];else if(k==='height'&&Number.isFinite(saved[k]))state[k]=Math.max(350,Math.min(750,saved[k]));}}catch{}
const get=id=>document.getElementById(id),root=document.documentElement;
const dialog=document.createElement('dialog');dialog.id='appearance-dialog';dialog.className='appearance-dialog';dialog.setAttribute('aria-labelledby','appearance-title');dialog.innerHTML=`<div class="appearance-header"><div><div class="eyebrow">MAKE IT YOURS</div><h2 id="appearance-title">Your workspace</h2></div><button id="appearance-close" class="outline" aria-label="Close customization">✕</button></div><div class="appearance-body"><p>Themes, chart preferences and layout settings save automatically in this browser.</p><h3>Choose a theme</h3><div class="theme-grid">${[['midnight','Midnight','#0c1015','#18212a'],['graphite','Graphite','#151515','#353535'],['ocean','Deep ocean','#071823','#174052'],['plum','Plum','#17111e','#472d5a'],['paper','Paper','#f1f4f7','#fff'],['contrast','High contrast','#000','#454545']].map(([id,name,bg,panel])=>`<button class="theme-card" data-theme-choice="${id}" aria-pressed="false"><span class="theme-preview" style="--preview-bg:${bg};--preview-panel:${panel}"></span>${name}</button>`).join('')}</div><h3>Color & layout</h3><div class="prefs-grid"><label>ACCENT<select id="pref-accent"><option value="lime">Lime</option><option value="cyan">Cyan</option><option value="violet">Violet</option><option value="amber">Amber</option></select></label><label>DENSITY<select id="pref-density"><option value="comfortable">Comfortable</option><option value="compact">Compact</option></select></label><label>PAGE WIDTH<select id="pref-layout"><option value="standard">Standard</option><option value="wide">Full width</option></select></label><label>MARKET CHART STYLE<select id="pref-chartStyle"><option value="1">Candlesticks</option><option value="2">Line</option><option value="3">Area</option></select></label><label>MARKET INTERVAL<select id="pref-marketInterval"><option value="1">1 minute</option><option value="5">5 minutes</option><option value="15">15 minutes</option><option value="60">1 hour</option><option value="D">1 day</option></select></label></div><label class="height-label">MARKET CHART HEIGHT <span id="height-value"></span><input id="pref-height" type="range" min="350" max="750" step="10"></label><label class="pref-toggle"><span>Accessible candle colors<small>Use blue / orange for the demo charts and P&L.</small></span><input id="pref-colorblind" type="checkbox"></label><h3>Candlestick colors</h3><p>Choose rising and falling colors separately for each practice chart. Bodies and wicks use the same color. Accessible candle colors overrides these choices while enabled. The external TradingView chart has its own settings.</p><div class="prefs-grid candle-colors"><label>STOCK · RISING<input id="pref-stockUp" type="color"></label><label>STOCK · FALLING<input id="pref-stockDown" type="color"></label><label>OPTION PREMIUM · RISING<input id="pref-premiumUp" type="color"></label><label>OPTION PREMIUM · FALLING<input id="pref-premiumDown" type="color"></label></div><h3>Show what matters</h3><label class="pref-toggle"><span>Market view only<small>Hide simulated quotes, option panels and paper positions.</small></span><input id="pref-marketOnly" type="checkbox"></label><label class="pref-toggle"><span>Stock search & list</span><input id="pref-showList" type="checkbox"></label><label class="pref-toggle"><span>Option chain & order ticket<small>Shown when market view only is off.</small></span><input id="pref-showChain" type="checkbox"></label><label class="pref-toggle"><span>Positions table<small>Shown when market view only is off.</small></span><input id="pref-showPositions" type="checkbox"></label><h3>Quick layouts</h3><div class="preset-buttons"><button id="preset-market" class="outline">Market focus</button><button id="preset-options" class="outline">Options practice</button></div><div class="appearance-bottom"><button id="appearance-reset" class="outline">Reset appearance</button><p id="appearance-status" class="appearance-status" role="status">Defaults loaded. Positions and stock lists are unaffected by appearance changes.</p></div></div>`;document.body.appendChild(dialog);
window.DeskAppearance={get:()=>({...state}),palette:(isOption=false)=>{const css=getComputedStyle(root),up=state.colorblind?css.getPropertyValue('--candle-up').trim():state[isOption?'premiumUp':'stockUp'],down=state.colorblind?css.getPropertyValue('--candle-down').trim():state[isOption?'premiumDown':'stockDown'];return{grid:css.getPropertyValue('--line').trim(),text:css.getPropertyValue('--muted').trim(),up,down,ema:css.getPropertyValue('--ema').trim()};}};
function apply(persist=true){root.dataset.theme=state.theme;root.dataset.accent=state.accent;root.dataset.density=state.density;root.dataset.layout=state.layout;root.dataset.marketOnly=String(state.marketOnly);root.dataset.showList=String(state.showList);root.dataset.showChain=String(state.showChain);root.dataset.showPositions=String(state.showPositions);root.dataset.colorblind=String(state.colorblind);root.style.setProperty('--market-height',state.height+'px');get('height-value').textContent=state.height+' px';for(const k of Object.keys(defaults)){const el=get('pref-'+k);if(el){if(typeof defaults[k]==='boolean')el.checked=state[k];else el.value=state[k];}}
for(const b of document.querySelectorAll('[data-theme-choice]'))b.setAttribute('aria-pressed',String(b.dataset.themeChoice===state.theme));get('market-interval').value=state.marketInterval;if(persist)try{localStorage.setItem(key,JSON.stringify(state));get('appearance-status').textContent='Preferences saved in this browser.';}catch{get('appearance-status').textContent='Browser storage unavailable. Changes last this session.';}document.dispatchEvent(new CustomEvent('desk:appearance'));window.dispatchEvent(new Event('resize'));}
get('customize').onclick=()=>get('appearance-dialog').showModal();get('appearance-close').onclick=()=>get('appearance-dialog').close();for(const b of document.querySelectorAll('[data-theme-choice]'))b.onclick=()=>{state.theme=b.dataset.themeChoice;apply();};for(const k of Object.keys(defaults)){const el=get('pref-'+k);if(el)el.addEventListener(k==='height'||/^(stock|premium)(Up|Down)$/.test(k)?'input':'change',()=>{state[k]=typeof defaults[k]==='boolean'?el.checked:k==='height'?Number(el.value):el.value;apply();});}
get('preset-market').onclick=()=>{state.marketOnly=true;state.showList=true;state.height=600;state.layout='wide';apply();};get('preset-options').onclick=()=>{state.marketOnly=false;state.showChain=true;state.showPositions=true;state.showList=true;state.density='compact';state.height=450;apply();};get('appearance-reset').onclick=()=>{state={...defaults};apply();};get('market-interval').addEventListener('change',e=>{state.marketInterval=e.target.value;try{localStorage.setItem(key,JSON.stringify(state));}catch{}});apply(false);
})();
